    # Initialize counts for all statuses
    counts = {"new": 0, "applied": 0, "rejected": 0, "other": 0}

    for job in jobs:
        # Get status, handle missing or None case
        status = job.get("status")
        if status is None:
            counts["other"] += 1
        else:
            # Normalize status: strip whitespace and convert to lowercase
            normalized_status = str(status).strip().lower()
            # Map to appropriate category
            if normalized_status == "new":
                counts["new"] += 1
            elif normalized_status == "applied":
                counts["applied"] += 1
            elif normalized_status == "rejected":
                counts["rejected"] += 1
            else:
                counts["other"] += 1

    return counts"}
